```typescript
1	import { useEffect, useState } from "react";
2	
3	const BAR_COUNT = 40;
4	const IDLE_LEVEL = 0.08;
5	const UPDATE_MS = 33;
6	const CENTER_EMPHASIS = 0.35;
7	const BOOST_OFFSET = 0.04;
8	const BOOST_CURVE = 0.55;
9	const BOOST_GAIN = 2.8;
10	
11	const createIdleLevels = (): number[] => Array.from({ length: BAR_COUNT }, () => IDLE_LEVEL);
12	
13	const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
14	
15	function computeLevels(dataArray: Uint8Array, bufferLength: number): number[] {
16	  const sampled: number[] = [];
17	  for (let i = 0; i < BAR_COUNT; i++) {
18	    const start = Math.floor((i / BAR_COUNT) * bufferLength);
19	    const end = Math.floor(((i + 1) / BAR_COUNT) * bufferLength);
20	    let sum = 0;
21	    for (let j = start; j < end; j++) {
22	      sum += dataArray[j];
23	    }
24	    const span = Math.max(1, end - start);
25	    const avg = sum / (255 * span);
26	    const boosted = Math.min(1, (avg + BOOST_OFFSET) ** BOOST_CURVE * BOOST_GAIN);
27	    sampled.push(Math.max(IDLE_LEVEL, boosted));
28	  }
29	
30	  const mirrored: number[] = [];
31	  for (let i = 0; i < BAR_COUNT; i++) {
32	    const j = BAR_COUNT - 1 - i;
33	    const v = (sampled[i] + sampled[j]) / 2;
34	    const centerDistance = Math.abs(i - (BAR_COUNT - 1) / 2) / (BAR_COUNT / 2);
35	    const envelope = 1 - centerDistance * CENTER_EMPHASIS;
36	    mirrored.push(Math.max(IDLE_LEVEL, clamp01(v * envelope)));
37	  }
38	
39	  for (let i = 1; i < BAR_COUNT - 1; i++) {
40	    mirrored[i] = Math.max(IDLE_LEVEL, (mirrored[i - 1] + mirrored[i] * 2 + mirrored[i + 1]) / 4);
41	  }
42	
43	  return mirrored;
44	}
45	
46	/**
47	 * Derives normalized bar levels (0–1) from a microphone MediaStream for live waveform UI.
48	 */
49	export function useAudioWaveform(stream: MediaStream | null, enabled: boolean): number[] {
50	  const [levels, setLevels] = useState<number[]>(createIdleLevels);
51	
52	  useEffect(() => {
53	    if (!enabled || !stream) {
54	      setLevels(createIdleLevels());
55	      return;
56	    }
57	
58	    const audioContext = new AudioContext();
59	    const source = audioContext.createMediaStreamSource(stream);
60	    const analyser = audioContext.createAnalyser();
61	    analyser.fftSize = 512;
62	    analyser.minDecibels = -72;
63	    analyser.maxDecibels = -8;
64	    analyser.smoothingTimeConstant = 0.72;
65	    source.connect(analyser);
66	
67	    const bufferLength = analyser.frequencyBinCount;
68	    const dataArray = new Uint8Array(bufferLength);
69	    let rafId = 0;
70	    let lastEmit = 0;
71	    let first = true;
72	
73	    const tick = (now: number) => {
74	      analyser.getByteFrequencyData(dataArray);
75	      if (first || now - lastEmit >= UPDATE_MS) {
76	        first = false;
77	        lastEmit = now;
78	        setLevels(computeLevels(dataArray, bufferLength));
79	      }
80	      rafId = requestAnimationFrame(tick);
81	    };
82	
83	    const start = async () => {
84	      await audioContext.resume();
85	      rafId = requestAnimationFrame(tick);
86	    };
87	
88	    void start();
89	
90	    return () => {
91	      cancelAnimationFrame(rafId);
92	      source.disconnect();
93	      analyser.disconnect();
94	      void audioContext.close();
95	    };
96	  }, [stream, enabled]);
97	
98	  return levels;
99	}
