3	const BAR_COUNT = 40;
4	const IDLE_LEVEL = 0.08;
5	const UPDATE_MS = 33;
6	const CENTER_EMPHASIS = 0.35;
7	const BOOST_OFFSET = 0.04;
8	const BOOST_CURVE = 0.55;
9	const BOOST_GAIN = 2.8;
10	
11	const createIdleLevels = (): number[] => Array.from({ length: BAR_COUNT }, () => IDLE_LEVEL);
12	
13	const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
14	
15	function computeLevels(dataArray: Uint8Array, bufferLength: number): number[] {
16	  const sampled: number[] = [];
17	  for (let i = 0; i < BAR_COUNT; i++) {
18	    const start = Math.floor((i / BAR_COUNT) * bufferLength);
19	    const end = Math.floor(((i + 1) / BAR_COUNT) * bufferLength);
20	    let sum = 0;
21	    for (let j = start; j < end; j++) {
22	      sum += dataArray[j];
23	    }
24	    const span = Math.max(1, end - start);
25	    const avg = sum / (255 * span);
26	    const boosted = Math.min(1, (avg + BOOST_OFFSET) ** BOOST_CURVE * BOOST_GAIN);
27	    sampled.push(Math.max(IDLE_LEVEL, boosted));
28	  }
29	
30	  const mirrored: number[] = [];
31	  for (let i = 0; i < BAR_COUNT; i++) {
32	    const j = BAR_COUNT - 1 - i;
33	    const v = (sampled[i] + sampled[j]) / 2;
34	    const centerDistance = Math.abs(i - (BAR_COUNT - 1) / 2) / (BAR_COUNT / 2);
35	    const envelope = 1 - centerDistance * CENTER_EMPHASIS;
36	    mirrored.push(Math.max(IDLE_LEVEL, clamp01(v * envelope)));
37	  }
38	
39	  for (let i = 1; i < BAR_COUNT - 1; i++) {
40	    mirrored[i] = Math.max(IDLE_LEVEL, (mirrored[i - 1] + mirrored[i] * 2 + mirrored[i + 1]) / 4);
41	  }
42	
43	  return mirrored;
44	}
