63	    analyser.maxDecibels = -8;
64	    analyser.smoothingTimeConstant = 0.72;
65	    source.connect(analyser);
66	
67	    const bufferLength = analyser.frequencyBinCount;
68	    const dataArray = new Uint8Array(bufferLength);
69	    let rafId = 0;
70	    let lastEmit = 0;
71	    let first = true;
72	
73	    const tick = (now: number) => {
74	      analyser.getByteFrequencyData(dataArray);
75	      if (first || now - lastEmit >= UPDATE_MS) {
76	        first = false;
77	        lastEmit = now;
78	        setLevels(computeLevels(dataArray, bufferLength));
79	      }
80	      rafId = requestAnimationFrame(tick);
81	    };
82	
